</main></div></div><div x-show="open" x-cloak class="fixed inset-0 bg-slate-950/60 z-40 lg:hidden" @click="open=false"></div><script>document.querySelectorAll('form[data-confirm]').forEach(f=>f.addEventListener('submit',e=>{if(!confirm(f.dataset.confirm))e.preventDefault()}));</script><script>(function(){const r=document.documentElement,s=localStorage.getItem('paroko-admin-theme');if(s==='dark'||s==='light')r.dataset.theme=s;const b=document.getElementById('adminThemeToggle'),i=document.getElementById('adminThemeIcon');function sync(){const d=r.dataset.theme==='dark';if(i){i.setAttribute('data-icon',d?'solar:sun-2-linear':'solar:moon-linear');if(window.Iconify)Iconify.scan(i)}}b?.addEventListener('click',()=>{r.dataset.theme=r.dataset.theme==='dark'?'light':'dark';localStorage.setItem('paroko-admin-theme',r.dataset.theme);sync()});sync()})();</script></body></html>
